// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _runTest(uint256 amount) internal {
        try c.AdjustBetAmounts(amount) {} catch { return; }
        uint256 observed;
        try c.currentBetLimit() returns (uint256 __r) { observed = __r; } catch { return; }
        assertTrue(observed == amount);
    }

    function testFuzz_runTest(uint256 amount) public {
        _runTest(amount);
    }

    receive() external payable {}
}
